begin;

create table public.return_documents(
 id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete restrict,branch_id uuid not null references public.branches(id) on delete restrict,
 return_type text not null check(return_type in('sales_return','purchase_return')),document_number text not null,return_date date not null,source_invoice_id uuid not null,contact_id uuid not null,
 status text not null default 'draft' check(status in('draft','pending_approval','approved','rejected','posted','reversed')),reason text not null,subtotal numeric(24,4) not null default 0,tax_total numeric(24,4) not null default 0,total numeric(24,4) not null default 0,
 journal_entry_id uuid references public.journal_entries(id) on delete restrict,reversal_journal_id uuid references public.journal_entries(id) on delete restrict,
 submitted_by uuid references auth.users(id),submitted_at timestamptz,approved_by uuid references auth.users(id),approved_at timestamptz,rejected_by uuid references auth.users(id),rejected_at timestamptz,rejection_reason text,posted_by uuid references auth.users(id),posted_at timestamptz,reversed_by uuid references auth.users(id),reversed_at timestamptz,reversal_reason text,
 created_at timestamptz not null default now(),created_by uuid not null references auth.users(id),updated_at timestamptz,updated_by uuid references auth.users(id),version integer not null default 1 check(version>0),unique(company_id,id),unique(company_id,document_number),foreign key(company_id,contact_id) references public.contacts(company_id,id) on delete restrict
);
create table public.return_document_lines(
 id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete restrict,return_id uuid not null,line_number integer not null check(line_number>0),source_line_id uuid not null,product_id uuid not null,warehouse_id uuid,
 description text not null,quantity numeric(24,6) not null check(quantity>0),unit_amount numeric(24,6) not null check(unit_amount>=0),discount_amount numeric(24,4) not null default 0,net_amount numeric(24,4) not null,tax_amount numeric(24,4) not null default 0,total numeric(24,4) not null,account_id uuid not null,tax_account_id uuid,
 created_at timestamptz not null default now(),created_by uuid references auth.users(id),unique(return_id,line_number),foreign key(company_id,return_id) references public.return_documents(company_id,id) on delete cascade,foreign key(company_id,product_id) references public.products(company_id,id) on delete restrict,foreign key(company_id,warehouse_id) references public.warehouses(company_id,id) on delete restrict,foreign key(company_id,account_id) references public.chart_of_accounts(company_id,id) on delete restrict,foreign key(company_id,tax_account_id) references public.chart_of_accounts(company_id,id) on delete restrict
);
create table public.contact_credits(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete restrict,contact_id uuid not null,return_id uuid not null,credit_type text not null check(credit_type in('customer_credit','supplier_debit')),original_amount numeric(24,4) not null check(original_amount>0),available_amount numeric(24,4) not null check(available_amount>=0),status text not null default 'open' check(status in('open','applied','reversed')),created_at timestamptz not null default now(),created_by uuid references auth.users(id),unique(company_id,return_id),foreign key(company_id,contact_id) references public.contacts(company_id,id) on delete restrict,foreign key(company_id,return_id) references public.return_documents(company_id,id) on delete restrict);
create trigger return_documents_updated before update on public.return_documents for each row execute function public.set_updated_metadata();create trigger return_documents_audit after insert or update or delete on public.return_documents for each row execute function public.audit_row_change();
alter table public.return_documents enable row level security;alter table public.return_document_lines enable row level security;alter table public.contact_credits enable row level security;
create policy return_documents_read on public.return_documents for select to authenticated using(public.current_user_has_permission(company_id,case return_type when 'sales_return' then 'sales.read' else 'purchase.read' end));create policy return_lines_read on public.return_document_lines for select to authenticated using(exists(select 1 from public.return_documents document where document.id=return_document_lines.return_id and public.current_user_has_permission(document.company_id,case document.return_type when 'sales_return' then 'sales.read' else 'purchase.read' end)));create policy contact_credits_read on public.contact_credits for select to authenticated using(public.current_user_has_company_access(company_id));grant select on public.return_documents,public.return_document_lines,public.contact_credits to authenticated;

create or replace function public.next_return_number(p_company_id uuid,p_date date,p_branch_id uuid,p_type text) returns text language plpgsql volatile security definer set search_path='' as $$ declare v_sequence public.document_sequences%rowtype;v_period text;v_value bigint;v_number text;v_width integer;v_code text:=case p_type when 'sales_return' then 'SR' when 'purchase_return' then 'PRT' end;begin if v_code is null then raise exception using message='Tipe retur tidak valid.';end if;select * into v_sequence from public.document_sequences where company_id=p_company_id and document_type=v_code and branch_scope=coalesce(p_branch_id,'00000000-0000-0000-0000-000000000000'::uuid) for update;if not found then insert into public.document_sequences(company_id,branch_id,document_type,pattern,reset_frequency,created_by) values(p_company_id,p_branch_id,v_code,v_code||'-{YYYY}-{MM}-{####}','monthly',auth.uid()) returning * into v_sequence;end if;v_period:=to_char(p_date,'YYYY-MM');if v_sequence.current_period is distinct from v_period then v_value:=1;else v_value:=v_sequence.next_value;end if;update public.document_sequences set current_period=v_period,next_value=v_value+1 where id=v_sequence.id;v_number:=replace(replace(v_sequence.pattern,'{YYYY}',to_char(p_date,'YYYY')),'{MM}',to_char(p_date,'MM'));v_width:=coalesce(length((regexp_match(v_number,'\{(#+)\}'))[1]),0);return regexp_replace(v_number,'\{#+\}',lpad(v_value::text,v_width,'0'));end;$$;revoke all on function public.next_return_number(uuid,date,uuid,text) from public,anon,authenticated;

create or replace function public.save_return_document(p_company_id uuid,p_return_id uuid,p_return_type text,p_source_invoice_id uuid,p_return_date date,p_reason text,p_lines jsonb,p_version integer default null)
returns uuid language plpgsql volatile security definer set search_path='' as $$
declare v_id uuid;v_doc public.return_documents%rowtype;v_source record;v_line record;v_original record;v_no integer:=0;v_net numeric;v_tax numeric;v_subtotal numeric:=0;v_tax_total numeric:=0;v_domain text:=case p_return_type when 'sales_return' then 'sales' else 'purchase' end;
begin if p_return_type not in('sales_return','purchase_return') or not public.current_user_has_permission(p_company_id,v_domain||case when p_return_id is null then '.create' else '.update' end) then raise exception using errcode='42501',message='Tidak memiliki izin menyimpan retur.';end if;if length(trim(p_reason))<5 or jsonb_typeof(p_lines)<>'array' or jsonb_array_length(p_lines)=0 then raise exception using message='Alasan dan baris retur wajib diisi.';end if;
 if p_return_type='sales_return' then select id,branch_id,customer_id contact_id into v_source from public.sales_invoices where company_id=p_company_id and id=p_source_invoice_id and status in('posted','partially_paid','paid');else select id,branch_id,supplier_id contact_id into v_source from public.purchase_invoices where company_id=p_company_id and id=p_source_invoice_id and status in('posted','partially_paid','paid');end if;if not found then raise exception using message='Invoice posted tidak ditemukan.';end if;
 if p_return_id is null then insert into public.return_documents(company_id,branch_id,return_type,document_number,return_date,source_invoice_id,contact_id,reason,created_by) values(p_company_id,v_source.branch_id,p_return_type,'DRAFT-'||upper(substr(p_return_type,1,2))||'-'||substr(gen_random_uuid()::text,1,8),p_return_date,p_source_invoice_id,v_source.contact_id,trim(p_reason),auth.uid()) returning id into v_id;else select * into v_doc from public.return_documents where company_id=p_company_id and id=p_return_id and return_type=p_return_type for update;if not found or v_doc.status not in('draft','rejected') or v_doc.version<>p_version then raise exception using message='Draft retur berubah atau tidak ditemukan.';end if;update public.return_documents set return_date=p_return_date,reason=trim(p_reason),status='draft',rejection_reason=null,updated_by=auth.uid() where id=p_return_id;delete from public.return_document_lines where return_id=p_return_id;v_id:=p_return_id;end if;
 for v_line in select * from jsonb_to_recordset(p_lines) as x(source_line_id uuid,warehouse_id uuid,quantity numeric) loop v_no:=v_no+1;if p_return_type='sales_return' then select line.*,coalesce(tax.rate,0) tax_rate,code.output_account_id tax_account into v_original from public.sales_invoice_lines line left join public.tax_rate_versions tax on tax.id=line.tax_rate_version_id left join public.tax_codes code on code.id=tax.tax_code_id where line.company_id=p_company_id and line.invoice_id=p_source_invoice_id and line.id=v_line.source_line_id;else select line.*,coalesce(tax.rate,0) tax_rate,code.input_account_id tax_account into v_original from public.purchase_invoice_lines line left join public.tax_rate_versions tax on tax.id=line.tax_rate_version_id left join public.tax_codes code on code.id=tax.tax_code_id where line.company_id=p_company_id and line.invoice_id=p_source_invoice_id and line.id=v_line.source_line_id;end if;if not found or v_line.quantity<=0 then raise exception using message='Baris sumber retur tidak valid.';end if;if v_line.quantity+coalesce((select sum(existing.quantity) from public.return_document_lines existing join public.return_documents document on document.id=existing.return_id where existing.source_line_id=v_line.source_line_id and document.status in('pending_approval','approved','posted') and document.id<>coalesce(p_return_id,'00000000-0000-0000-0000-000000000000'::uuid)),0)>v_original.quantity then raise exception using message='Kuantitas retur melebihi invoice.';end if;if exists(select 1 from public.products where id=v_original.product_id and product_type='inventory') and(v_line.warehouse_id is null or not exists(select 1 from public.warehouses where company_id=p_company_id and id=v_line.warehouse_id and is_active)) then raise exception using message='Gudang wajib untuk produk inventory.';end if;v_net:=round(v_line.quantity*v_original.quantity::numeric^(-1)*(v_original.quantity*case p_return_type when 'sales_return' then v_original.unit_price else v_original.unit_cost end-v_original.discount_amount),4);v_tax:=round(v_net*v_original.tax_rate/100,4);v_subtotal:=v_subtotal+v_net;v_tax_total:=v_tax_total+v_tax;insert into public.return_document_lines(company_id,return_id,line_number,source_line_id,product_id,warehouse_id,description,quantity,unit_amount,discount_amount,net_amount,tax_amount,total,account_id,tax_account_id,created_by) values(p_company_id,v_id,v_no,v_line.source_line_id,v_original.product_id,v_line.warehouse_id,v_original.description,v_line.quantity,case p_return_type when 'sales_return' then v_original.unit_price else v_original.unit_cost end,round(v_line.quantity/v_original.quantity*v_original.discount_amount,4),v_net,v_tax,v_net+v_tax,case p_return_type when 'sales_return' then v_original.revenue_account_id else v_original.expense_account_id end,v_original.tax_account,auth.uid());end loop;update public.return_documents set subtotal=v_subtotal,tax_total=v_tax_total,total=v_subtotal+v_tax_total where id=v_id;return v_id;end;$$;

create or replace function public.delete_return_draft(p_company_id uuid,p_return_id uuid,p_version integer) returns void language plpgsql volatile security definer set search_path='' as $$ declare v_type text;begin select return_type into v_type from public.return_documents where company_id=p_company_id and id=p_return_id;if not public.current_user_has_permission(p_company_id,case v_type when 'sales_return' then 'sales.update' else 'purchase.update' end) then raise exception using errcode='42501',message='Tidak memiliki izin menghapus retur.';end if;delete from public.return_documents where company_id=p_company_id and id=p_return_id and version=p_version and status in('draft','rejected');if not found then raise exception using message='Draft retur tidak dapat dihapus.';end if;end;$$;
create or replace function public.submit_return_document(p_company_id uuid,p_return_id uuid) returns uuid language plpgsql volatile security definer set search_path='' as $$ declare v_doc public.return_documents%rowtype;v_request uuid;v_number text;v_domain text;begin select * into v_doc from public.return_documents where company_id=p_company_id and id=p_return_id and status in('draft','rejected') for update;if not found then raise exception using message='Draft retur tidak ditemukan.';end if;v_domain:=case v_doc.return_type when 'sales_return' then 'sales' else 'purchase' end;if not public.current_user_has_permission(p_company_id,v_domain||'.submit') then raise exception using errcode='42501',message='Tidak memiliki izin submit retur.';end if;v_number:=case when v_doc.document_number like 'DRAFT-%' then public.next_return_number(p_company_id,v_doc.return_date,v_doc.branch_id,v_doc.return_type) else v_doc.document_number end;insert into public.approval_requests(company_id,document_type,document_id,document_number,submitted_by,created_by) values(p_company_id,v_doc.return_type,p_return_id,v_number,auth.uid(),auth.uid()) on conflict(company_id,document_type,document_id) do update set status='pending',document_number=excluded.document_number,submitted_by=auth.uid(),submitted_at=now(),completed_at=null returning id into v_request;insert into public.approval_actions(company_id,request_id,step,action,actor_user_id) values(p_company_id,v_request,0,'submit',auth.uid());update public.return_documents set document_number=v_number,status='pending_approval',submitted_by=auth.uid(),submitted_at=now(),updated_by=auth.uid() where id=p_return_id;return v_request;end;$$;
create or replace function public.decide_return_document(p_company_id uuid,p_return_id uuid,p_action text,p_comment text default null) returns void language plpgsql volatile security definer set search_path='' as $$ declare v_doc public.return_documents%rowtype;v_request uuid;v_domain text;v_allow boolean:=false;begin select * into v_doc from public.return_documents where company_id=p_company_id and id=p_return_id and status='pending_approval' for update;if not found then raise exception using message='Retur menunggu persetujuan tidak ditemukan.';end if;v_domain:=case v_doc.return_type when 'sales_return' then 'sales' else 'purchase' end;if p_action not in('approve','reject') or not public.current_user_has_permission(p_company_id,v_domain||'.approve') then raise exception using errcode='42501',message='Tidak memiliki izin persetujuan retur.';end if;select allow_self_approval into v_allow from public.company_settings where company_id=p_company_id;if not coalesce(v_allow,false) and v_doc.submitted_by=auth.uid() then raise exception using errcode='42501',message='Pembuat retur tidak boleh menyetujui sendiri.';end if;if p_action='reject' and length(trim(coalesce(p_comment,'')))<5 then raise exception using message='Alasan penolakan minimal lima karakter.';end if;select id into v_request from public.approval_requests where company_id=p_company_id and document_type=v_doc.return_type and document_id=p_return_id and status='pending' for update;update public.approval_requests set status=case p_action when 'approve' then 'approved' else 'rejected' end,completed_at=now() where id=v_request;insert into public.approval_actions(company_id,request_id,step,action,actor_user_id,comment) values(p_company_id,v_request,1,p_action,auth.uid(),nullif(trim(p_comment),''));if p_action='approve' then update public.return_documents set status='approved',approved_by=auth.uid(),approved_at=now(),updated_by=auth.uid() where id=p_return_id;else update public.return_documents set status='rejected',rejected_by=auth.uid(),rejected_at=now(),rejection_reason=trim(p_comment),updated_by=auth.uid() where id=p_return_id;end if;end;$$;

create or replace function public.post_return_document(p_company_id uuid,p_return_id uuid,p_idempotency_key text) returns uuid language plpgsql volatile security definer set search_path='' as $$
declare v_doc public.return_documents%rowtype;v_line record;v_balance public.product_warehouses%rowtype;v_journal uuid;v_domain text;v_control uuid;v_no integer:=0;v_cost numeric;v_new_qty numeric;v_new_value numeric;v_new_avg numeric;
begin select * into v_doc from public.return_documents where company_id=p_company_id and id=p_return_id for update;if not found then raise exception using message='Retur tidak ditemukan.';end if;if v_doc.status='posted' then return v_doc.journal_entry_id;end if;if v_doc.status<>'approved' then raise exception using message='Hanya retur approved yang dapat diposting.';end if;v_domain:=case v_doc.return_type when 'sales_return' then 'sales' else 'purchase' end;if not public.current_user_has_permission(p_company_id,v_domain||'.post') then raise exception using errcode='42501',message='Tidak memiliki izin posting retur.';end if;if not exists(select 1 from public.accounting_periods where company_id=p_company_id and v_doc.return_date between starts_on and ends_on and status='open') then raise exception using message='Periode akuntansi tidak terbuka.';end if;select account_id into v_control from public.account_mappings where company_id=p_company_id and mapping_code=case v_doc.return_type when 'sales_return' then 'accounts_receivable' else 'accounts_payable' end;if v_control is null then raise exception using message='Pemetaan akun kontrol belum lengkap.';end if;
 insert into public.journal_entries(company_id,branch_id,journal_number,document_date,journal_date,posting_date,description,status,source_type,source_id,total_debit,total_credit,idempotency_key,posted_by,posted_at,created_by) values(p_company_id,v_doc.branch_id,v_doc.document_number||'/J',v_doc.return_date,v_doc.return_date,v_doc.return_date,'Retur '||v_doc.document_number,'draft',v_doc.return_type,p_return_id,0,0,p_idempotency_key,auth.uid(),now(),auth.uid()) returning id into v_journal;
 if v_doc.return_type='sales_return' then v_no:=v_no+1;insert into public.journal_lines(company_id,journal_entry_id,account_id,line_number,description,debit,credit,base_debit,base_credit,branch_id,contact_id,created_by) values(p_company_id,v_journal,v_control,v_no,'Kredit pelanggan',0,v_doc.total,0,v_doc.total,v_doc.branch_id,v_doc.contact_id,auth.uid());else v_no:=v_no+1;insert into public.journal_lines(company_id,journal_entry_id,account_id,line_number,description,debit,credit,base_debit,base_credit,branch_id,contact_id,created_by) values(p_company_id,v_journal,v_control,v_no,'Debit pemasok',v_doc.total,0,v_doc.total,0,v_doc.branch_id,v_doc.contact_id,auth.uid());end if;
 for v_line in select line.*,product.product_type,product.inventory_account_id,product.cogs_account_id,product.name from public.return_document_lines line join public.products product on product.id=line.product_id where line.return_id=p_return_id order by line.line_number loop v_no:=v_no+1;insert into public.journal_lines(company_id,journal_entry_id,account_id,line_number,description,debit,credit,base_debit,base_credit,branch_id,contact_id,created_by) values(p_company_id,v_journal,v_line.account_id,v_no,v_line.description,case when v_doc.return_type='sales_return' then v_line.net_amount else 0 end,case when v_doc.return_type='purchase_return' then v_line.net_amount else 0 end,case when v_doc.return_type='sales_return' then v_line.net_amount else 0 end,case when v_doc.return_type='purchase_return' then v_line.net_amount else 0 end,v_doc.branch_id,v_doc.contact_id,auth.uid());if v_line.tax_amount>0 then if v_line.tax_account_id is null then raise exception using message='Akun pajak retur tidak tersedia.';end if;v_no:=v_no+1;insert into public.journal_lines(company_id,journal_entry_id,account_id,line_number,description,debit,credit,base_debit,base_credit,branch_id,contact_id,created_by) values(p_company_id,v_journal,v_line.tax_account_id,v_no,'Pajak retur',case when v_doc.return_type='sales_return' then v_line.tax_amount else 0 end,case when v_doc.return_type='purchase_return' then v_line.tax_amount else 0 end,case when v_doc.return_type='sales_return' then v_line.tax_amount else 0 end,case when v_doc.return_type='purchase_return' then v_line.tax_amount else 0 end,v_doc.branch_id,v_doc.contact_id,auth.uid());end if;
  if v_line.product_type='inventory' then insert into public.product_warehouses(company_id,product_id,warehouse_id,created_by) values(p_company_id,v_line.product_id,v_line.warehouse_id,auth.uid()) on conflict(company_id,product_id,warehouse_id) do nothing;select * into v_balance from public.product_warehouses where company_id=p_company_id and product_id=v_line.product_id and warehouse_id=v_line.warehouse_id for update;if v_doc.return_type='sales_return' then v_cost:=round(v_line.quantity*coalesce(nullif(v_balance.average_cost,0),v_line.unit_amount),4);v_new_qty:=v_balance.quantity_on_hand+v_line.quantity;v_new_value:=v_balance.inventory_value+v_cost;v_new_avg:=round(v_new_value/v_new_qty,6);else if v_line.quantity>v_balance.quantity_on_hand then raise exception using message='Stok tidak cukup untuk retur pembelian '||v_line.name;end if;v_cost:=round(v_line.quantity*v_balance.average_cost,4);v_new_qty:=v_balance.quantity_on_hand-v_line.quantity;v_new_value:=greatest(0,v_balance.inventory_value-v_cost);v_new_avg:=case when v_new_qty=0 then 0 else round(v_new_value/v_new_qty,6) end;end if;update public.product_warehouses set quantity_on_hand=v_new_qty,inventory_value=v_new_value,average_cost=v_new_avg,last_movement_date=v_doc.return_date,updated_by=auth.uid() where id=v_balance.id;insert into public.inventory_movements(company_id,product_id,warehouse_id,movement_date,movement_type,quantity,unit_cost,total_cost,running_quantity,running_average_cost,source_type,source_id,source_line_id,created_by) values(p_company_id,v_line.product_id,v_line.warehouse_id,v_doc.return_date,case v_doc.return_type when 'sales_return' then 'return_in' else 'return_out' end,case v_doc.return_type when 'sales_return' then v_line.quantity else -v_line.quantity end,case when v_line.quantity=0 then 0 else v_cost/v_line.quantity end,v_cost,v_new_qty,v_new_avg,v_doc.return_type,p_return_id,v_line.id,auth.uid());if v_doc.return_type='sales_return' then v_no:=v_no+1;insert into public.journal_lines(company_id,journal_entry_id,account_id,line_number,description,debit,credit,base_debit,base_credit,branch_id,created_by) values(p_company_id,v_journal,v_line.inventory_account_id,v_no,'Persediaan retur',v_cost,0,v_cost,0,v_doc.branch_id,auth.uid());v_no:=v_no+1;insert into public.journal_lines(company_id,journal_entry_id,account_id,line_number,description,debit,credit,base_debit,base_credit,branch_id,created_by) values(p_company_id,v_journal,v_line.cogs_account_id,v_no,'Pembalikan HPP',0,v_cost,0,v_cost,v_doc.branch_id,auth.uid());end if;end if;end loop;
 update public.journal_entries set total_debit=(select sum(debit) from public.journal_lines where journal_entry_id=v_journal),total_credit=(select sum(credit) from public.journal_lines where journal_entry_id=v_journal),status='posted' where id=v_journal;if v_doc.return_type='sales_return' then update public.sales_invoices set outstanding_balance=greatest(0,outstanding_balance-v_doc.total),status=case when greatest(0,outstanding_balance-v_doc.total)=0 then 'paid' else 'partially_paid' end where id=v_doc.source_invoice_id;update public.accounts_receivable set outstanding_amount=greatest(0,outstanding_amount-v_doc.total),status=case when greatest(0,outstanding_amount-v_doc.total)=0 then 'paid' else 'partially_paid' end where sales_invoice_id=v_doc.source_invoice_id;else update public.purchase_invoices set outstanding_balance=greatest(0,outstanding_balance-v_doc.total),status=case when greatest(0,outstanding_balance-v_doc.total)=0 then 'paid' else 'partially_paid' end where id=v_doc.source_invoice_id;update public.accounts_payable set outstanding_amount=greatest(0,outstanding_amount-v_doc.total),status=case when greatest(0,outstanding_amount-v_doc.total)=0 then 'paid' else 'partially_paid' end where purchase_invoice_id=v_doc.source_invoice_id;end if;insert into public.contact_credits(company_id,contact_id,return_id,credit_type,original_amount,available_amount,created_by) values(p_company_id,v_doc.contact_id,p_return_id,case v_doc.return_type when 'sales_return' then 'customer_credit' else 'supplier_debit' end,v_doc.total,v_doc.total,auth.uid());update public.return_documents set status='posted',journal_entry_id=v_journal,posted_by=auth.uid(),posted_at=now(),updated_by=auth.uid() where id=p_return_id;return v_journal;
exception when unique_violation then select journal_entry_id into v_journal from public.return_documents where id=p_return_id;return v_journal;end;$$;

create or replace function public.reverse_return_document(p_company_id uuid,p_return_id uuid,p_date date,p_reason text,p_idempotency_key text) returns uuid language plpgsql volatile security definer set search_path='' as $$ declare v_doc public.return_documents%rowtype;v_move public.inventory_movements%rowtype;v_balance public.product_warehouses%rowtype;v_reversal uuid;v_new_qty numeric;v_new_value numeric;v_new_avg numeric;begin select * into v_doc from public.return_documents where company_id=p_company_id and id=p_return_id and status='posted' for update;if not found or length(trim(p_reason))<5 then raise exception using message='Retur posted atau alasan tidak valid.';end if;if not public.current_user_has_permission(p_company_id,case v_doc.return_type when 'sales_return' then 'sales.post' else 'purchase.post' end) or not public.current_user_has_permission(p_company_id,'journal.reverse') then raise exception using errcode='42501',message='Tidak memiliki izin reversal retur.';end if;for v_move in select * from public.inventory_movements where company_id=p_company_id and source_type=v_doc.return_type and source_id=p_return_id order by created_at desc loop if exists(select 1 from public.inventory_movements later where later.company_id=p_company_id and later.product_id=v_move.product_id and later.warehouse_id=v_move.warehouse_id and later.created_at>v_move.created_at) then raise exception using message='Reversal diblokir karena ada movement berikutnya.';end if;select * into v_balance from public.product_warehouses where company_id=p_company_id and product_id=v_move.product_id and warehouse_id=v_move.warehouse_id for update;v_new_qty:=v_balance.quantity_on_hand-v_move.quantity;if v_new_qty<0 then raise exception using message='Reversal membuat stok negatif.';end if;v_new_value:=case when v_move.quantity>0 then greatest(0,v_balance.inventory_value-v_move.total_cost) else v_balance.inventory_value+v_move.total_cost end;v_new_avg:=case when v_new_qty=0 then 0 else round(v_new_value/v_new_qty,6) end;update public.product_warehouses set quantity_on_hand=v_new_qty,inventory_value=v_new_value,average_cost=v_new_avg,last_movement_date=p_date,updated_by=auth.uid() where id=v_balance.id;insert into public.inventory_movements(company_id,product_id,warehouse_id,movement_date,movement_type,quantity,unit_cost,total_cost,running_quantity,running_average_cost,source_type,source_id,source_line_id,created_by) values(p_company_id,v_move.product_id,v_move.warehouse_id,p_date,case when v_move.quantity>0 then 'return_out' else 'return_in' end,-v_move.quantity,v_move.unit_cost,v_move.total_cost,v_new_qty,v_new_avg,v_doc.return_type||'_reversal',p_return_id,v_move.source_line_id,auth.uid());end loop;v_reversal:=public.reverse_journal_entry_core(p_company_id,v_doc.journal_entry_id,p_date,p_reason,p_idempotency_key);update public.contact_credits set status='reversed',available_amount=0 where return_id=p_return_id;update public.return_documents set status='reversed',reversal_journal_id=v_reversal,reversed_by=auth.uid(),reversed_at=now(),reversal_reason=trim(p_reason),updated_by=auth.uid() where id=p_return_id;return v_reversal;end;$$;

revoke all on function public.save_return_document(uuid,uuid,text,uuid,date,text,jsonb,integer) from public,anon;revoke all on function public.delete_return_draft(uuid,uuid,integer) from public,anon;revoke all on function public.submit_return_document(uuid,uuid) from public,anon;revoke all on function public.decide_return_document(uuid,uuid,text,text) from public,anon;revoke all on function public.post_return_document(uuid,uuid,text) from public,anon;revoke all on function public.reverse_return_document(uuid,uuid,date,text,text) from public,anon;
grant execute on function public.save_return_document(uuid,uuid,text,uuid,date,text,jsonb,integer) to authenticated;grant execute on function public.delete_return_draft(uuid,uuid,integer) to authenticated;grant execute on function public.submit_return_document(uuid,uuid) to authenticated;grant execute on function public.decide_return_document(uuid,uuid,text,text) to authenticated;grant execute on function public.post_return_document(uuid,uuid,text) to authenticated;grant execute on function public.reverse_return_document(uuid,uuid,date,text,text) to authenticated;

commit;
